import json, sys
def simulate_bucket(data: dict) -> dict:
    cap = float(data['capacity'])
    rate = float(data['refill_rate'])
    state = {}
    decisions = []
    for req in data.get('requests', []):
        cid, ts = req['client_id'], int(req['timestamp'])
        tokens, last_ts = state.get(cid, (cap, ts))
        tokens = min(cap, tokens + ((ts - last_ts) // 1) * rate)
        if tokens >= 1.0:
            decisions.append(True)
            state[cid] = (tokens - 1.0, ts)
        else:
            decisions.append(False)
            state[cid] = (tokens, ts)
    return {'decisions': decisions}
